package com.xyz.question_bank_management_system.modules.agent.tool;
import com.xyz.question_bank_management_system.exception.*;import com.xyz.question_bank_management_system.modules.knowledge.entity.*;import com.xyz.question_bank_management_system.modules.knowledge.mapper.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;import java.util.*;
@Component @RequiredArgsConstructor public class KnowledgeGraphSearchTool {private final KnowledgeGraphVersionMapper versionMapper;private final KnowledgeGraphVersionRelationMapper relationMapper;public Map<String,Object> query(Long courseId,Collection<Long> ids){KnowledgeGraphVersion v=versionMapper.selectActive(courseId);if(v==null)throw BizException.of(ErrorCode.KNOWLEDGE_GRAPH_UNAVAILABLE,"没有 ACTIVE 图版本");List<KnowledgeGraphVersionRelation> rows=relationMapper.selectByVersion(v.getId()).stream().filter(r->ids.contains(r.getSourceKnowledgePointId())&&ids.contains(r.getTargetKnowledgePointId())).toList();return Map.of("graphVersion",v.getVersionCode(),"relations",rows);}}
